 const wanted=new Map();for(const member of room.members||[])for(const preference of member.preferences?.wants||[]){const name=preference.name?.replace(/市$/,'');const city=cities.find(item=>item.id===preference.id||item.name.replace(/市$/,'')===name);if(city?.point)wanted.set(city.id,city)}
