const blank=()=>({tab:'map',origin:'杭州',days:3,budget:null,mood:'吃吃逛逛',date:'',arrival:'11:00',departure:'18:00',saved:[],customCities:[],dismissed:[],history:[],planHistory:{},preferredProvinces:[],excludedProvinces:[],dartRangeConfirmed:false,selected:null,plans:{},active:null,day:0,group:false,actor:'you',votes:{},version:1,confirmations:{},savedPlan:false});let state=blank();try{const raw=JSON.parse(localStorage.getItem('nextstop-demo-v1')||'null');if(raw?.schema===1){state={...state,...raw.data};state.saved=state.saved.filter(id=>cities.some(c=>c.id===id));state.tab=['map','pool','plan','room'].includes(state.tab)?state.tab:'map'}}catch{}state.group=false;state.actor='you';const ROOM_RETURN_KEY='nextstop-room-return-id';let roomReturnId=null;try{roomReturnId=state.tab==='plan'?(sessionStorage.getItem(ROOM_RETURN_KEY)||state.roomDrafts?.[state.active]?.roomId||sessionStorage.getItem('nextstop-active-room')):null}catch{}let geo=null,projection=null,throwing=false,toastTimer,pendingEdit=null,undoPlan=null,shareMode=false;

