async function runAI(payload){
 if(throwing)return false;throwing=true;const controller=new AbortController();aiController=controller;
 const timeout=setTimeout(()=>controller.abort('timeout'),325000);
 sheet(payload.mode==='lodging'?'安安正在挑选住处':payload.mode==='replace'?'安安正在找新的去处':payload.previousStops?'安安正在重新安排':'安安正在推荐下一站', '<div class="loading-panel" role="status" aria-live="polite"><div class="loading-icon">'+icon('compass')+'</div><h2>把期待，排进日程。</h2><p>'+esc(payload.city.name)+' · '+payload.options.days+' 天<br>正在结合旅行时段和偏好生成推荐</p><small>正在安排路线并查询费用参考，可能需要几分钟；完成前不会修改原草稿。</small></div>','<button class="secondary" data-action="cancel-ai">取消等待</button>');
 try{
  const r=await fetch('/api/itinerary',{method:'POST',headers:{'Content-Type':'application/json','X-Trip-Visitor':aiVisitor},body:JSON.stringify(payload),signal:controller.signal});
  let d;try{d=await r.json()}catch{throw Error('服务暂时没有响应，请稍后重试。')}
  if(!r.ok){if(d.code==='AI_NOT_CONFIGURED')aiStatus='missing';const failure=Error(d.message||'生成失败，请稍后重试。');failure.code=d.code;throw failure}
  if(aiController!==controller)return false;
  aiStatus='configured';throwing=false;aiController=null;
  if(payload.mode==='lodging'){
    capturePlanStatus();const old=state.plans[payload.city.id];rememberUndo(old);old.lodging=TripDetails.cleanLodging(d.lodging,true);state.active=payload.city.id;invalidate();persist();close();navigate('plan');toast('住宿建议已补充，原来的路线和三餐安排已保留');
  }else if(payload.mode==='replace'){
    const old=state.plans[payload.city.id],next=JSON.parse(JSON.stringify(old));next.days[payload.day].stops[payload.index]=d.stop;pendingEdit=next;
    previewChange('把「'+old.days[payload.day].stops[payload.index].name+'」换成「'+d.stop.name+'」',old,next,'安安的建议。保留原时段、停留时长和其他站点，确认后才会替换。');
  }else{
    capturePlanStatus();rememberUndo(state.plans[payload.city.id]);
    if(undoPlan?.confirmedStay)d.plan.confirmedStay=undoPlan.confirmedStay;if(undoPlan?.actualExpenses)d.plan.actualExpenses=undoPlan.actualExpenses.map(x=>({...x,day:Math.min(x.day,d.plan.days.length)}));if(undoPlan?.manualEstimate)d.plan.manualEstimate=undoPlan.manualEstimate;state.plans[payload.city.id]=d.plan;state.active=payload.city.id;state.version=(undoPlan?.status?.version||0)+1;state.savedPlan=false;state.confirmations={};state.day=0;
    if(!state.saved.includes(payload.city.id))state.saved.push(payload.city.id);
    state.date=payload.options.date;
    persist();close();navigate('plan');try{const synced=await roomUI.autoShare();toast(synced?'新方案已生成并同步到房间':payload.previousStops?'新方案已生成，可继续调整或撤销恢复上一版':'安安把行程排好了，可以保留喜欢的站点，再慢慢调整')}catch{toast('新方案已保存在本机，房间同步失败，请点击保存重试')}
  }
  return true;
 }catch(e){
  if(aiController!==controller)return false;throwing=false;aiController=null;
  const message=controller.signal.aborted?'这次等待超时了。原草稿仍保留，可以重试。':e instanceof TypeError?'网络没有连通，请检查连接后重试。':e.message;
  sheet('这次还没生成好','<p class="ai-error" role="alert">'+esc(message)+'</p><p>城市和这次填写的偏好都还在，原行程也没有被覆盖。</p>', '<button class="secondary" data-action="setup" data-id="'+payload.city.id+'">调整条件</button>'+'<button class="primary" data-action="retry-ai">重新尝试</button>');
  return false;
 }finally{clearTimeout(timeout)}
}
let comparisonIds=[];
function poolTools(){return `<div class="pool-tools"><button class="secondary" data-action="compare-cities" ${state.saved.length<2?'disabled':''}>${icon('columns-2')}对比城市${state.saved.length<2?' · 至少 2 座':''}</button><button class="secondary" data-action="picker">${icon('plus')}添加城市</button></div>`;}
