 const p=state.plans[state.active],item=kind==='meals'?p.days[state.day].meals?.find(m=>m.type===index):p.lodging?.[kind]?.[Number(index)];if(!item)return;
 const fields=kind==='meals'?[['area','用餐地区或餐厅',80],['suggestion','想吃什么',200],['note','用餐备注',200]]:kind==='areas'?[['name','住宿地区',60],['reason','选择理由',250],['transport','交通说明',200]]:[['name','酒店名称',100],['area','所在地区',60],['reason','选择理由',250]];
