let sheetTouchStart=null;
document.addEventListener('touchstart',event=>{sheetTouchStart=event.target.closest('#sheet')&&event.touches.length===1?{x:event.touches[0].clientX,y:event.touches[0].clientY}:null},{passive:true});
document.addEventListener('touchmove',event=>{if(!sheetTouchStart||!event.target.closest('#sheet')||!event.cancelable)return;const dx=event.touches[0].clientX-sheetTouchStart.x,dy=event.touches[0].clientY-sheetTouchStart.y;if(Math.abs(dx)>10&&Math.abs(dx)>Math.abs(dy)*1.2)event.preventDefault()},{passive:false});
document.addEventListener('touchend',()=>{sheetTouchStart=null},{passive:true});
document.addEventListener('wheel',event=>{if(event.target.closest('#sheet')&&Math.abs(event.deltaX)>Math.abs(event.deltaY)&&event.cancelable)event.preventDefault()},{passive:false});
